// Plus Jakarta Sans (OFL-licentie, © The Plus Jakarta Sans Project Authors —
// https://github.com/tokotype/PlusJakartaSans) voor de PDF's: facturen,
// offertes en brieven. Het StudioBaris-lettertype, dus hetzelfde als op
// studiobaris.nl, de werkplek en de preview-tool.
//
// Als base64 ingebakken — zelfde aanpak als het vroegere Bodoni-bestand —
// zodat er geen los lettertypebestand bestaat dat op Vercel kan ontbreken.
// Gesubset tot Latijnse tekens + leestekens + € (scheelt ~60% grootte);
// genoeg voor Nederlandse tekst, ook wat Claude in brieven schrijft.
//
// Gebruik: const { font, vet, italic, merk } = await jakartaFonts(pdf);
//   font   = Regular (400)   lopende tekst
//   vet    = Bold (700)      labels, bedragen
//   italic = Italic (400)    ondertitels
//   merk   = ExtraBold (800) wordmark "StudioBaris", het "B"-blokje, grote koppen
import fontkit from "@pdf-lib/fontkit";

const JAKARTA_REGULAR_BASE64 =
  "";

const JAKARTA_BOLD_BASE64 =
  "";

const JAKARTA_EXTRABOLD_BASE64 =
  "";

const JAKARTA_ITALIC_BASE64 =
  "";

export async function jakartaFonts(pdf) {
  pdf.registerFontkit(fontkit);
  const laad = (b64) => pdf.embedFont(Buffer.from(b64, "base64"), { subset: true });
  const [font, vet, italic, merk] = await Promise.all([
    laad(JAKARTA_REGULAR_BASE64),
    laad(JAKARTA_BOLD_BASE64),
    laad(JAKARTA_ITALIC_BASE64),
    laad(JAKARTA_EXTRABOLD_BASE64),
  ]);
  return { font, vet, italic, merk };
}
